def solve(inputs: dict) -> float:
    rems = inputs['remainders']
    mods = inputs['moduli']

    # Extended GCD to find modular inverse
    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        gcd, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y

    def mod_inverse(a, m):
        gcd, x, _ = extended_gcd(a % m, m)
        if gcd != 1:
            return None
        return (x % m + m) % m

    # Chinese Remainder Theorem
    def crt(rems, mods):
        # Assuming all moduli are pairwise coprime
        M = 1
        for m in mods:
            M *= m

        x = 0
        for i in range(len(rems)):
            Mi = M // mods[i]
            yi = mod_inverse(Mi, mods[i])
            x += rems[i] * Mi * yi

        return x % M

    result = crt(rems, mods)
    return float(result)

