    M = inputs['matrix']
    power = inputs['power']
    mod = inputs['modulus']

    # Convert to list of lists if needed
    if not isinstance(M, list):
        M = M.tolist() if hasattr(M, 'tolist') else [[M[i][j] for j in range(len(M[0]))] for i in range(len(M))]

    n = len(M)

    # Matrix multiplication modulo mod
    def matrix_mult(A, B, mod):
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                for k in range(n):
                    result[i][j] = (result[i][j] + A[i][k] * B[k][j]) % mod
        return result

    # Matrix exponentiation using binary exponentiation
    def matrix_pow(M, p, mod):
        # Identity matrix
        result = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
        base = [row[:] for row in M]  # Copy M

        while p > 0:
            if p % 2 == 1:
                result = matrix_mult(result, base, mod)
            base = matrix_mult(base, base, mod)
            p //= 2

        return result

    M_pow = matrix_pow(M, power, mod)

    # Sum all entries
    total = sum(sum(row) for row in M_pow)
    return float(total % mod)

